/**
 * Rows stored before an event moved to a new action key keep their old key and stay until
 * retention removes them. The Action filter offers the new key only and queries both, so
 * one option covers the whole history.
 *
 * Admin accounts: remove together with the deprecated `user.*` event hub events.
 */
export declare const LEGACY_ACTIONS: Record<string, string>;
export declare const isLegacyAction: (action: string) => boolean;
/**
 * Rewrites `action` equality conditions on a new key into `$in` / `$notIn` over the new
 * and the legacy key. Walks `$and`, `$or` and `$not`. Anything else is returned as is.
 */
export declare const expandLegacyActionFilters: <T>(filters: T) => T;
/** Expands the action filters of a list query, leaving pagination and sort as they are. */
export declare const expandLegacyActionQuery: <T extends {
    filters?: unknown;
}>(query: T) => T;
